import { createPushGate } from "./bot.mjs";
const assert = (c, m) => { if (!c) { console.error("FAIL", m); process.exitCode = 1; } else console.log("ok", m); };
const u = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const at = (iso) => new Date(iso);
let g = createPushGate();
assert(g.attempt(u, at("2026-10-23T12:00:00+09:00")).allowed === true, "midday allowed");
assert(g.attempt(u, at("2026-10-23T22:00:00+09:00")).reason === "quiet_hours", "22:00 start is quiet");
assert(g.attempt(u, at("2026-10-23T06:59:00+09:00")).reason === "quiet_hours", "06:59 still quiet");
assert(g.attempt(u, at("2026-10-23T07:00:00+09:00")).allowed === true, "07:00 end is not quiet");
g = createPushGate();
assert(g.attempt(u, at("2026-10-23T08:00:00+09:00")).allowed, "cap 1");
assert(g.attempt(u, at("2026-10-23T09:00:00+09:00")).allowed, "cap 2");
assert(g.attempt(u, at("2026-10-23T10:00:00+09:00")).allowed, "cap 3");
assert(g.attempt(u, at("2026-10-23T11:00:00+09:00")).reason === "daily_cap_reached", "cap 4 refused");
assert(g.attempt(u, at("2026-10-23T23:59:00+09:00")).reason === "quiet_hours", "quiet beats cap");
assert(g.attempt(u, at("2026-10-24T08:00:00+09:00")).allowed, "new local day resets cap");
const ny = { id: "u_1", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 1 };
g = createPushGate();
assert(g.attempt(ny, at("2026-10-23T12:00:00-04:00")).allowed, "NY day 1");
assert(g.attempt(ny, at("2026-10-23T12:00:00Z")).reason === "daily_cap_reached", "same NY day across UTC date");
assert(g.attempt(ny, at("2026-10-24T12:00:00-04:00")).allowed, "NY next day");
assert(createPushGate().attempt({ ...u, id: "u_x" }, at("2026-10-23T12:00:00+09:00")).allowed, "fresh gate independent");
assert(g.attempt({ ...u, id: "u_other", dailyCap: 1 }, at("2026-10-23T12:00:00+09:00")).allowed, "other user independent");
assert(g.attempt({ ...u, timeZone: "Mars/Olympus" }, at("2026-10-23T12:00:00+09:00")).reason === "invalid_timezone", "bad zone held");
assert(g.attempt({ ...u, id: "u_q", quietStart: "25:00" }, at("2026-10-23T12:00:00+09:00")).reason === "invalid_quiet_hours", "bad quiet held");
assert(g.attempt({ ...u, id: "u_c", dailyCap: 1.5 }, at("2026-10-23T12:00:00+09:00")).reason === "invalid_daily_cap", "bad cap held");
const eq = { ...u, id: "u_eq", quietStart: "10:00", quietEnd: "10:00" };
assert(createPushGate().attempt(eq, at("2026-10-23T10:00:00+09:00")).allowed, "equal start/end means no quiet");
'
